import { readFile, writeFile } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const root = resolve(dirname(fileURLToPath(import.meta.url)), "..");
const contracts = [
  ["PayGuardActionRouter", "PayGuardActionRouter.sol"],
  ["PayGuardFoundationSender", "PayGuardFoundationSender.sol"],
  ["PayGuardPolicyRegistry", "PayGuardPolicyRegistry.sol"],
  ["PayGuardVault", "PayGuardVault.sol"],
];

const sections = [
  "// This file is generated by tooling/generate-bindings.mjs.",
  "// Source: packages/contracts/out/*/*.json; do not edit by hand.",
  "",
];
for (const [name, source] of contracts) {
  const artifactPath = resolve(root, "packages/contracts/out", source, `${name}.json`);
  let artifact;
  try {
    artifact = JSON.parse(await readFile(artifactPath, "utf8"));
  } catch (error) {
    throw new Error(`missing Foundry artifact ${artifactPath}; run forge build first`, { cause: error });
  }
  if (!Array.isArray(artifact.abi)) throw new Error(`artifact has no ABI: ${artifactPath}`);
  sections.push(`export const ${name}Abi = ${JSON.stringify(artifact.abi, null, 2)} as const;`, "");
}

const requestedOutput = process.argv[2];
const output = requestedOutput ? resolve(root, requestedOutput) : resolve(root, "packages/bindings/src/generated.ts");
await writeFile(output, `${sections.join("\n").replace(/\n+$/, "")}\n`, "utf8");
console.log(JSON.stringify({ status: "ok", output: output.replace(`${root}/`, ""), contracts: contracts.map(([name]) => name) }));
